window.CenizasPreferences=(()=>{let auto=false;try{auto=localStorage.getItem('cenizas-battle-auto-close')==='true';}catch{}function sync(){document.querySelectorAll('[data-battle-auto]').forEach(el=>el.checked=auto);}document.querySelectorAll('[data-battle-auto]').forEach(el=>el.addEventListener('change',()=>{auto=el.checked;try{localStorage.setItem('cenizas-battle-auto-close',String(auto));}catch{}sync();window.dispatchEvent(new Event('battle-auto-change'));}));sync();return {get auto(){return auto;}};})();
